import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DoubleSide, Vector2 } = ctx.THREE;

  // Root container
  const root = new Group();

  // Determine plane size from atlas region (width:height = 512:320)
  const aspect = 512 / 320;
  const geometry = new PlaneGeometry(aspect, 1);

  // Basic material; texture will be assigned asynchronously
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    side: DoubleSide,
    // Ensure node material uses UV coordinates (default is uv())
    uvNode: uv(),
  });

  const mesh = new Mesh(geometry, material);
  // No explicit interaction handlers for this static sprite
  mesh.userData.handlers = {};

  root.add(mesh);

  // Load the texture and apply it when ready
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    material.map = tex;
    material.needsUpdate = true;
  });

  // Cleanup routine to dispose all allocated resources
  root.userData.cleanup = () => {
    // Dispose texture if it was set
    if (material.map) {
      material.map.dispose();
    }
    material.dispose();
    geometry.dispose();
    // Remove references
    mesh.geometry = null;
    mesh.material = null;
    root.clear();
  };

  return root;
}
